KG42.register("nodes-98d2c9b111b24b79cfca6bfa",{"id":"COMP-bf4a00350a51bde7","code":"PRC015","label":"Purchase and sale pricing using metered supply-demand ratios and compensation terms","definition":"The P2P buying and selling unit prices are formed according to the aggregate metered supply-demand ratio SDR^t, the grid purchase and sale prices, and the compensation price λ. When 0≤SDR^t≤1, Pr_{sell}^t=((λ_{sell,t}+λ)λ_{buy,t})/((λ_{buy,t}-λ_{sell,t}-λ)SDR^t+λ_{sell,t}+λ), Pr_{buy}^t=Pr_{sell}^t·SDR^t+λ_{buy,t}(1-SDR^t); when SDR^t>1, Pr_{sell}^t=λ_{sell,t}+λ/SDR^t, Pr_{buy}^t=λ_{sell,t}+λ.","layer":"L6","template_code":"JOC","concept_id":"pricing.local","concept_ids":["pricing.local"],"identity_dimensions":{"identity_fields":["Object: community P2P electricity purchase and sale unit prices","Core operation: piecewise pricing based on the aggregate supply-demand ratio, external electricity prices, and the compensation term","Output: Pr_{buy}^t and Pr_{sell}^t"]},"exclusions":["SDR^t=[sum_{i=1}^{N_B}(P_{PV,t}^i-P_{aggBC,t}^i+P_{aggBD,t}^i)]/[sum_{i=1}^{N}P_{L,t}^i]","Pricing is recorded using smart meters after 24 h of consumption; there is no iteration between price and control activities","0≤λ≤λ_{buy,t}-λ_{sell,t}; the ESC adjusts the compensation price based on customer assessment","Price bounds: Pr_{buy}^t≤λ_{buy,t}, Pr_{sell}^t≥λ_{sell,t}","The source specifies the endpoints: when SDR^t=0, both prices are λ_{buy,t}; when SDR^t=1, both prices are λ_{sell,t}+λ","The bill selects the already-formed buying price or selling price according to the customer's net position; the original text does not list the zero net position case"],"members":[{"id":"19-two_stage_battery_sharing::v141-c-R005::V::pricing.local","rule_id":"v141-c-R005","market_meaning":"The ESC manages and adjusts the compensating price included in the local P2P pricing mechanism. Scope: Community P2P energy sharing under modified SDR pricing; compensation adjustment informed by customer assessment. The P2P buying price should not exceed the grid buying price, and the P2P selling price should not fall below the grid selling price. Scope: Buying and selling prices within the P2P sharing community. P2P pricing is conducted 24 h after actual electricity consumption using recorded import/export energy data from smart meters. Scope: Ex-post pricing within the P2P sharing community. P2P trading prices are calculated using the SDR method, with the dynamic supply and demand ratio obtained from aggregated metered supply and demand. Scope: Community P2P trading prices calculated from the previous 24 h of premises' smart-metering data. The compensating price is bounded between zero and the difference between the grid buying and selling prices. Scope: Compensating component of the community's modified SDR pricing mechanism. Both P2P selling and buying prices equal the price of electricity bought from the main grid. Scope: Community P2P buying and selling prices at time t. Condition: SDR^{t} = 0; there is no selling power in the community. Both P2P selling and buying prices equal the grid selling price plus the compensating price. Scope: Community P2P buying and selling prices at time t. Condition: SDR^{t} = 1; community selling power equals buying power.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"pricing","context_text":"Buying and selling prices within the P2P sharing community. | Community P2P buying and selling prices at time t. | Community P2P energy sharing under modified SDR pricing; compensation adjustment informed by customer assessment. | Community P2P trading prices calculated from the previous 24 h of premises' smart-metering data. | Compensating component of the community's modified SDR pricing mechanism. | Ex-post pricing within the P2P sharing community.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e013","v141-b-g01-e014","v141-b-g02-E10","v141-b-g02-E21","v141-b-g02-E23","v141-b-g04-E12"]},"constraint_refs":["19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C001","19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C002","19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C003","19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C004","19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C005","19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C006","19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C007","19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C008","19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C009"],"decision_anchor":"pricing.local","source_rule_sha256":"96395fa5d5e547fb54dd66802ad10eec3cad2948cbd6c7b49fe199d6b9e43676","paper":"19-two_stage_battery_sharing","rule_ref":"19-two_stage_battery_sharing::v141-c-R005","node_id":"pricing.local","function":"pricing.local","unit_id":"19-two_stage_battery_sharing::v141-a-M01::pricing.local","mechanism_id":"v141-a-M01","anchor":true},{"id":"19-two_stage_battery_sharing::v141-c-R007::V::pricing.local","rule_id":"v141-c-R007","market_meaning":"The ESC administers settlement by calculating individual customer energy bills and ensuring that prosumers’ income balances consumers’ expenditure. Scope: Individual customer settlement in the ESC-operated P2P sharing community. Local P2P pricing determines the electricity bills that prosumers pay or receive as repayments and that consumers pay. Scope: Electricity-bill payments and repayments of prosumers and consumers contracted with the ESC. The source states that the P2P buying-price ceiling implies lower consumer electricity bills under P2P sharing than under P2G trading. Scope: Consumer electricity bills under P2P sharing compared with P2G trading. Condition: The P2P buying price never exceeds the price of electricity bought from the grid. Under this uncompensated pricing case, the source states that prosumer income is undermined while consumers benefit; prosumers may receive less income than without P2P sharing. Scope: The source’s explanation of prosumer income and consumer benefits under uncompensated SDR pricing. Condition: The compensating price is zero and the supply-to-demand ratio exceeds one, so both P2P prices equal the grid selling price. At every studied penetration level, zero compensation is reported to leave some prosumers paying higher electricity bills or receiving lower incomes when participating in P2P sharing. Scope: The reported sensitivity evaluation across the studied penetration levels of PV battery systems. Condition: The compensating price is zero in the reported evaluation. With an appropriate compensating price, modified local SDR pricing is stated to ensure economic benefits for every individual prosumer and consumer, with economic gains described in terms of bill savings or repayments. Scope: Individual prosumer and consumer financial outcomes under modified SDR pricing compared with conventional P2G trading. Condition: The compensating price is appropriately set. Billing is conducted 24 hours after actual electricity consumption using recorded import/export energy data from smart meters, for example half-hourly records. Scope: Customer billing in the proposed two-stage P2P sharing arrangement. The positive value is the amount of electricity bill the prosumer is required to pay. Scope: Prosumer electricity-bill values in the reported financial assessment. Condition: The reported prosumer bill value is positive. The negative value denotes income received by the prosumer. Scope: Prosumer electricity-bill values in the reported financial assessment. Condition: The reported prosumer bill value is negative.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Consumer electricity bills under P2P sharing compared with P2G trading. | Customer billing in the proposed two-stage P2P sharing arrangement. | Electricity-bill payments and repayments of prosumers and consumers contracted with the ESC. | Individual customer settlement in the ESC-operated P2P sharing community. | Individual prosumer and consumer financial outcomes under modified SDR pricing compared with conventional P2G trading. | Prosumer electricity-bill values in the reported financial assessment. | The reported sensitivity evaluation across the studied penetration levels of PV battery systems. | The source’s explanation of prosumer income and consumer benefits under uncompensated SDR pricing.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e002","v141-b-g01-e004","v141-b-g01-e005","v141-b-g01-e006","v141-b-g01-e013","v141-b-g02-E23","v141-b-g03-E13","v141-b-g04-E10","v141-b-g04-E13","v141-b-g04-E15","v141-b-g04-E17"]},"constraint_refs":["19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C002","19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C003","19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C004","19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C005","19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C006","19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C011","19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C012","19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C013","19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C014"],"decision_anchor":"settlement.payment","source_rule_sha256":"bd880e891130c0f37fb74ec2eeadfc37b72ff840ddc75d6776e532b766029c31","paper":"19-two_stage_battery_sharing","rule_ref":"19-two_stage_battery_sharing::v141-c-R007","node_id":"pricing.local","function":"pricing.local","unit_id":"19-two_stage_battery_sharing::v141-a-M01::pricing.local","mechanism_id":"v141-a-M01","anchor":false}],"paper_ids":["19-two_stage_battery_sharing"],"evidence":[{"evidence_id":"v141-b-g01-e014","location":{"location_id":"src-b91cee592e-p03-c2r4__v141-a-M01-participation","page":3,"printed_page":"263","section":"1. Introduction","anchor_text":"m DERs, because the pricing and billing are conducted 24 h after the ng actual electricity consumpti","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"restatement"},"source_text":"An innovative P2P pricing mechanism was developed to ensure all customers in a community gain economic benefits, i.e. being better off compared to the conventional P2G trading. This pricing mechanism is modified from a previous SDR mechanism to include a compensating price. The modified pricing mechanism can be used as a benchmark applicable to any P2P energy sharing model.","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R005","quote":"An innovative P2P pricing mechanism was developed to ensure all customers in a community gain economic benefits, i.e. being better off compared to the conventional P2G trading. This pricing mechanism is modified from a previous SDR mechanism to include a compensating price. The modified pricing mechanism can be used as a benchmark applicable to any P2P energy sharing model."},{"evidence_id":"v141-b-g02-E10","location":{"location_id":"src-b91cee592e-p06-c1r2__v141-a-M01-coordination","page":6,"printed_page":null,"section":null,"anchor_text":"psumer premises. The purposes of the control is to minimize the amount of electricity fed back to th","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"In the second block, the smart metering data at all the premises in the community are collected to calculate the aggregated supply and demand at different times of the day (for the previous 24 h). The dynamic supply and demand ratio is used to calculate the P2P trading prices using the SDR method. In practice, this is done 24 h after the actual electricity consumption, and therefore there are no iterations between the pricing and control activities. Finally, the assessment of the P2P energy sharing is carried out. In the community level, the self-consumption and self-sufficiency rate of the community, and the energy cost are analyzed. In the individual customer level, the energy cost of each customer is calculated and a participating willingness index is introduced to evaluate the willingness of prosumers participating in P2P energy sharing. This in turn helps the ESC to adjust the compensating price, which is used to ensure all customers in the community gain economic benefit.","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R005","quote":"In the second block, the smart metering data at all the premises in the community are collected to calculate the aggregated supply and demand at different times of the day (for the previous 24 h). The dynamic supply and demand ratio is used to calculate the P2P trading prices using the SDR method. In practice, this is done 24 h after the actual electricity consumption, and therefore there are no iterations between the pricing and control activities. Finally, the assessment of the P2P energy sharing is carried out. In the community level, the self-consumption and self-sufficiency rate of the community, and the energy cost are analyzed. In the individual customer level, the energy cost of each customer is calculated and a participating willingness index is introduced to evaluate the willingness of prosumers participating in P2P energy sharing. This in turn helps the ESC to adjust the compensating price, which is used to ensure all customers in the community gain economic benefit."},{"evidence_id":"v141-b-g04-E12","location":{"location_id":"src-b91cee592e-p14-c1r4__v141-a-M01-participation","page":14,"printed_page":null,"section":null,"anchor_text":"participation willingness, the lowest compensating prices were 4, 3.5, en 6, 8.5 and 7.5 pence, resp","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-14.png","occurrence_role":"condition"},"source_text":"Therefore, the penetration level of the PV battery systems in a community and the compensating prices managed by the ESC are the main factors to impact the participating willingness for P2P energy sharing, and they should be considered by prosumers and energy service companies when they initialize for P2P energy sharing.","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R005","quote":"Therefore, the penetration level of the PV battery systems in a community and the compensating prices managed by the ESC are the main factors to impact the participating willingness for P2P energy sharing, and they should be considered by prosumers and energy service companies when they initialize for P2P energy sharing."},{"evidence_id":"v141-b-g02-E21","location":{"location_id":"src-b91cee592e-p08-c2r2__v141-a-M01-pricing","page":8,"printed_page":null,"section":null,"anchor_text":"λ ( λ sell t + )·λbuy , , t3) 0 ⩽ SDRt ⩽ 1 ⎧ SDR − t + λ )· sell (λ buy , t − λ , t λ sell , t + λ t","equation_id":"(19)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"The P2P buying price (Pr_{buy}^{t}) should not be higher than the price of electricity bought from the grid (\\lambda_{buy,t}) and the P2P selling price (Pr_{sell}^{t}) should not be lower than the price of electricity sold to the grid (\\lambda_{sell,t}). Therefore, the P2P selling and buying prices are defined as a function of the SDR. They are shown as Pr_{sell}^{t} = f(SDR^{t}) = \\begin{cases} \\frac{(\\lambda_{sell,t} + \\lambda)\\lambda_{buy,t}}{(\\lambda_{buy,t} - \\lambda_{sell,t} - \\lambda)SDR^{t} + \\lambda_{sell,t} + \\lambda}, & 0 \\le SDR^{t} \\le 1 \\\\ \\lambda_{sell,t} + \\frac{\\lambda}{SDR^{t}}, & SDR^{t} > 1 \\end{cases} \\quad (19)","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R005","quote":"The P2P buying price (Pr_{buy}^{t}) should not be higher than the price of electricity bought from the grid (\\lambda_{buy,t}) and the P2P selling price (Pr_{sell}^{t}) should not be lower than the price of electricity sold to the grid (\\lambda_{sell,t}). Therefore, the P2P selling and buying prices are defined as a function of the SDR. They are shown as Pr_{sell}^{t} = f(SDR^{t}) = \\begin{cases} \\frac{(\\lambda_{sell,t} + \\lambda)\\lambda_{buy,t}}{(\\lambda_{buy,t} - \\lambda_{sell,t} - \\lambda)SDR^{t} + \\lambda_{sell,t} + \\lambda}, & 0 \\le SDR^{t} \\le 1 \\\\ \\lambda_{sell,t} + \\frac{\\lambda}{SDR^{t}}, & SDR^{t} > 1 \\end{cases} \\quad (19)"},{"evidence_id":"v141-b-g01-e013","location":{"location_id":"src-b91cee592e-p03-c2r3__v141-a-M01-coordination","page":3,"printed_page":"263","section":"1. Introduction","anchor_text":"in munity point of view, e.g. [19]. A thorough assessment method is ﬀ required to analyze the beneﬁt","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"restatement"},"source_text":"A novel two-stage aggregated control framework was proposed to realize P2P energy sharing in low voltage distribution networks. Comparing to the previous works of P2P energy sharing with a third party entity, this control framework requires for very limited measurements and a one-way communication, providing a feasible and practical solution to P2P energy sharing. Compared to the P2P energy sharing without an intermedia, there is no need of fast communication between the market operator and the individual DERs, because the pricing and billing are conducted 24 h after the actual electricity consumption, using the recorded import/export energy (e.g. half-hourly) data from smart meters. Also, there are no divergence issues.","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R005","quote":"A novel two-stage aggregated control framework was proposed to realize P2P energy sharing in low voltage distribution networks. Comparing to the previous works of P2P energy sharing with a third party entity, this control framework requires for very limited measurements and a one-way communication, providing a feasible and practical solution to P2P energy sharing. Compared to the P2P energy sharing without an intermedia, there is no need of fast communication between the market operator and the individual DERs, because the pricing and billing are conducted 24 h after the actual electricity consumption, using the recorded import/export energy (e.g. half-hourly) data from smart meters. Also, there are no divergence issues."},{"evidence_id":"v141-b-g02-E19","location":{"location_id":"src-b91cee592e-p08-c1r4__v141-a-M01-pricing","page":8,"printed_page":null,"section":null,"anchor_text":"3.3. P2P trading mechanism Given the fact that in economics the relation between price and SDR is in","equation_id":"(17)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"Given the fact that in economics the relation between price and SDR is inverse-proportional, reference [13] formulated a P2P pricing model based on the supply and demand ratio. Here, the SDR method is also used. The total selling power is from the PV battery systems, which is equal to the remaining PV power after carrying out the charging or discharging activities, and the total buying power is the customer demand. Thus, the SDR at a community Microgrid at time t is defined as, SDR^{t} = \\frac{\\sum_{i=1}^{NB} (P_{PV,t}^{i} - P_{aggBC,t}^{i} + P_{aggBD,t}^{i})}{\\sum_{i=1}^{N} P_{L,t}^{i}} \\quad (17)","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R005","quote":"Given the fact that in economics the relation between price and SDR is inverse-proportional, reference [13] formulated a P2P pricing model based on the supply and demand ratio. Here, the SDR method is also used. The total selling power is from the PV battery systems, which is equal to the remaining PV power after carrying out the charging or discharging activities, and the total buying power is the customer demand. Thus, the SDR at a community Microgrid at time t is defined as, SDR^{t} = \\frac{\\sum_{i=1}^{NB} (P_{PV,t}^{i} - P_{aggBC,t}^{i} + P_{aggBD,t}^{i})}{\\sum_{i=1}^{N} P_{L,t}^{i}} \\quad (17)"},{"evidence_id":"v141-b-g02-E23","location":{"location_id":"src-b91cee592e-p08-c2r3__v141-a-M01-pricing","page":8,"printed_page":null,"section":null,"anchor_text":"prices would dynamically change according to Eqs. (19) and (20). The relation of the P2P buying/sell","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"condition"},"source_text":"When SDR^{t} = 0, there is no selling power in the community, and all the required energy is bought from the main grid. The P2P selling and buying prices are both equal to the price of electricity bought from the grid (i.e. Pr_{sell}^{t} = Pr_{buy}^{t} = \\lambda_{buy,t}). When SDR^{t} = 1, the selling power is equal to the buying power in the community, and no power is required to import from (or export to) the main grid. The P2P selling and buying prices are both equal to the price of electricity sold to the grid with a compensation (i.e. Pr_{sell}^{t} = Pr_{buy}^{t} = \\lambda_{sell,t} + \\lambda). Here, \\lambda is a compensating price (0 \\le \\lambda \\le \\lambda_{buy,t} - \\lambda_{sell,t}), and it is used to compensate the prosumers to ensure the prosumers be better off when they participate in P2P energy sharing. When 0 \u003c SDR^{t} \u003c 1, or SDR^{t} > 1, the P2P selling and buying prices would dynamically change according to Eqs. (19) and (20). The reason for introducing the compensating price is that, when there is no compensating price (i.e. \\lambda = 0), both P2P selling and buying prices are equal to the price of electricity sold to grid when the SDR is more than 1. This will undermine the prosumers' income, but provide economic benefits to the consumers (i.e. these who do not have PV battery systems). It might happen that the prosumers receive lower incomes than the case of not participating in P2P energy sharing.","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R005","quote":"When SDR^{t} = 0, there is no selling power in the community, and all the required energy is bought from the main grid. The P2P selling and buying prices are both equal to the price of electricity bought from the grid (i.e. Pr_{sell}^{t} = Pr_{buy}^{t} = \\lambda_{buy,t}). When SDR^{t} = 1, the selling power is equal to the buying power in the community, and no power is required to import from (or export to) the main grid. The P2P selling and buying prices are both equal to the price of electricity sold to the grid with a compensation (i.e. Pr_{sell}^{t} = Pr_{buy}^{t} = \\lambda_{sell,t} + \\lambda). Here, \\lambda is a compensating price (0 \\le \\lambda \\le \\lambda_{buy,t} - \\lambda_{sell,t}), and it is used to compensate the prosumers to ensure the prosumers be better off when they participate in P2P energy sharing. When 0 \u003c SDR^{t} \u003c 1, or SDR^{t} > 1, the P2P selling and buying prices would dynamically change according to Eqs. (19) and (20). The reason for introducing the compensating price is that, when there is no compensating price (i.e. \\lambda = 0), both P2P selling and buying prices are equal to the price of electricity sold to grid when the SDR is more than 1. This will undermine the prosumers' income, but provide economic benefits to the consumers (i.e. these who do not have PV battery systems). It might happen that the prosumers receive lower incomes than the case of not participating in P2P energy sharing."},{"evidence_id":"v141-b-g02-E22","location":{"location_id":"src-b91cee592e-p08-c2r2__v141-a-M01-pricing","page":8,"printed_page":null,"section":null,"anchor_text":"λ ( λ sell t + )·λbuy , , t3) 0 ⩽ SDRt ⩽ 1 ⎧ SDR − t + λ )· sell (λ buy , t − λ , t λ sell , t + λ t","equation_id":"(20)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"Pr_{buy}^{t} = f'(SDR^{t}) = \\begin{cases} Pr_{sell}^{t} \\cdot SDR^{t} + \\lambda_{buy,t} \\cdot (1 - SDR^{t}), & 0 \\le SDR^{t} \\le 1 \\\\ \\lambda_{sell,t} + \\lambda, & SDR^{t} > 1 \\end{cases} \\quad (20)","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R005","quote":"Pr_{buy}^{t} = f'(SDR^{t}) = \\begin{cases} Pr_{sell}^{t} \\cdot SDR^{t} + \\lambda_{buy,t} \\cdot (1 - SDR^{t}), & 0 \\le SDR^{t} \\le 1 \\\\ \\lambda_{sell,t} + \\lambda, & SDR^{t} > 1 \\end{cases} \\quad (20)"},{"evidence_id":"v141-b-g01-e005","location":{"location_id":"src-b91cee592e-p04-c2r1__v141-a-M01-participation","page":4,"printed_page":"264","section":"2.1. P2P energy sharing structure","anchor_text":"Applied Energy 226 (2018) 261–276 the power balance of the community; Contract with a supplier for t","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"(2) Prosumers\n• Hand over the control of their batteries to the ESC;\n• Contract with the ESC, pay/repay their electricity bills according to the P2P pricing mechanism (The prices are calculated 24 h after the actual consumption according to the predefined pricing mechanism).","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R007","quote":"(2) Prosumers\n• Hand over the control of their batteries to the ESC;\n• Contract with the ESC, pay/repay their electricity bills according to the P2P pricing mechanism (The prices are calculated 24 h after the actual consumption according to the predefined pricing mechanism)."},{"evidence_id":"v141-b-g01-e006","location":{"location_id":"src-b91cee592e-p04-c2r2__v141-a-M01-participation","page":4,"printed_page":"264","section":"2.1. P2P energy sharing structure","anchor_text":"p g ( p he after the actual consumption according to the predeﬁned pricing is mechanism). (3) Consum","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"(3) Consumers\n• Contract with the ESC, pay their electricity bill according to the P2P pricing mechanism (The prices are calculated 24 h after the actual consumption according to the predefined pricing mechanism).","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R007","quote":"(3) Consumers\n• Contract with the ESC, pay their electricity bill according to the P2P pricing mechanism (The prices are calculated 24 h after the actual consumption according to the predefined pricing mechanism)."},{"evidence_id":"v141-b-g03-E13","location":{"location_id":"src-b91cee592e-p11-c1r2__v141-a-M01-participation","page":11,"printed_page":null,"section":null,"anchor_text":"sharing than under the P2G energy trading. Hence, there is no need to ti evaluate the participation ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-11.png","occurrence_role":"condition"},"source_text":"For the consumers, as the P2P buying price (Pr_{buy}^t) is never higher than the price of electricity bought from the grid (\\lambda_{buy,t}), the energy bill of consumers will be always lower when participating in P2P energy sharing than under the P2G energy trading. Hence, there is no need to evaluate the participation willingness of consumers.","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R007","quote":"For the consumers, as the P2P buying price (Pr_{buy}^t) is never higher than the price of electricity bought from the grid (\\lambda_{buy,t}), the energy bill of consumers will be always lower when participating in P2P energy sharing than under the P2G energy trading. Hence, there is no need to evaluate the participation willingness of consumers."},{"evidence_id":"v141-b-g02-E23","location":{"location_id":"src-b91cee592e-p08-c2r3__v141-a-M01-pricing","page":8,"printed_page":null,"section":null,"anchor_text":"prices would dynamically change according to Eqs. (19) and (20). The relation of the P2P buying/sell","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"condition"},"source_text":"When SDR^{t} = 0, there is no selling power in the community, and all the required energy is bought from the main grid. The P2P selling and buying prices are both equal to the price of electricity bought from the grid (i.e. Pr_{sell}^{t} = Pr_{buy}^{t} = \\lambda_{buy,t}). When SDR^{t} = 1, the selling power is equal to the buying power in the community, and no power is required to import from (or export to) the main grid. The P2P selling and buying prices are both equal to the price of electricity sold to the grid with a compensation (i.e. Pr_{sell}^{t} = Pr_{buy}^{t} = \\lambda_{sell,t} + \\lambda). Here, \\lambda is a compensating price (0 \\le \\lambda \\le \\lambda_{buy,t} - \\lambda_{sell,t}), and it is used to compensate the prosumers to ensure the prosumers be better off when they participate in P2P energy sharing. When 0 \u003c SDR^{t} \u003c 1, or SDR^{t} > 1, the P2P selling and buying prices would dynamically change according to Eqs. (19) and (20). The reason for introducing the compensating price is that, when there is no compensating price (i.e. \\lambda = 0), both P2P selling and buying prices are equal to the price of electricity sold to grid when the SDR is more than 1. This will undermine the prosumers' income, but provide economic benefits to the consumers (i.e. these who do not have PV battery systems). It might happen that the prosumers receive lower incomes than the case of not participating in P2P energy sharing.","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R007","quote":"When SDR^{t} = 0, there is no selling power in the community, and all the required energy is bought from the main grid. The P2P selling and buying prices are both equal to the price of electricity bought from the grid (i.e. Pr_{sell}^{t} = Pr_{buy}^{t} = \\lambda_{buy,t}). When SDR^{t} = 1, the selling power is equal to the buying power in the community, and no power is required to import from (or export to) the main grid. The P2P selling and buying prices are both equal to the price of electricity sold to the grid with a compensation (i.e. Pr_{sell}^{t} = Pr_{buy}^{t} = \\lambda_{sell,t} + \\lambda). Here, \\lambda is a compensating price (0 \\le \\lambda \\le \\lambda_{buy,t} - \\lambda_{sell,t}), and it is used to compensate the prosumers to ensure the prosumers be better off when they participate in P2P energy sharing. When 0 \u003c SDR^{t} \u003c 1, or SDR^{t} > 1, the P2P selling and buying prices would dynamically change according to Eqs. (19) and (20). The reason for introducing the compensating price is that, when there is no compensating price (i.e. \\lambda = 0), both P2P selling and buying prices are equal to the price of electricity sold to grid when the SDR is more than 1. This will undermine the prosumers' income, but provide economic benefits to the consumers (i.e. these who do not have PV battery systems). It might happen that the prosumers receive lower incomes than the case of not participating in P2P energy sharing."},{"evidence_id":"v141-b-g04-E10","location":{"location_id":"src-b91cee592e-p14-c1r3__v141-a-M01-participation","page":14,"printed_page":null,"section":null,"anchor_text":"battery, but it only requires to reduce the price of the battery system to ev £430/kWh (only 14% low","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-14.png","occurrence_role":"unknown"},"source_text":"When the compensating price is zero, at all the penetration levels of PV battery systems, some prosumers are paying more electricity bills or gaining lower incomes when participating in P2P energy sharing. This is because the economic beneﬁts were obtained by the consumers, whilst for some of the prosumers, it may not be worth participating in P2P energy sharing.","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R007","quote":"When the compensating price is zero, at all the penetration levels of PV battery systems, some prosumers are paying more electricity bills or gaining lower incomes when participating in P2P energy sharing. This is because the economic beneﬁts were obtained by the consumers, whilst for some of the prosumers, it may not be worth participating in P2P energy sharing."},{"evidence_id":"v141-b-g04-E15","location":{"location_id":"src-b91cee592e-p15-c1r3__v141-a-M01-participation","page":15,"printed_page":null,"section":null,"anchor_text":"pr This paper proposed a two-stage control method to realize P2P energy sharing in community Microgr","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-15.png","occurrence_role":"restatement"},"source_text":"With an appropriate setting of the compensating price, the modiﬁed supply demand ratio based mechanism ensures every individual customer in the community be better oﬀcompared to the conventional P2G energy trading, i.e. every individual prosumer and consumer gain economic beneﬁts. This pricing mechanism can be used as a benchmark applicable to any P2P energy sharing model.","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R007","quote":"With an appropriate setting of the compensating price, the modiﬁed supply demand ratio based mechanism ensures every individual customer in the community be better oﬀcompared to the conventional P2G energy trading, i.e. every individual prosumer and consumer gain economic beneﬁts. This pricing mechanism can be used as a benchmark applicable to any P2P energy sharing model."},{"evidence_id":"v141-b-g04-E17","location":{"location_id":"src-b91cee592e-p14-c2r3__v141-a-M01-coordination","page":14,"printed_page":null,"section":null,"anchor_text":"to evolutionary algorithms to achieve the global optimum for P2P energy sharing is considered as one","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-14.png","occurrence_role":"exception"},"source_text":"The unfairness of economic gains may exist, i.e. there are diﬀerences in bill savings (or repayments) among consumers (or prosumers).","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R007","quote":"The unfairness of economic gains may exist, i.e. there are diﬀerences in bill savings (or repayments) among consumers (or prosumers)."},{"evidence_id":"v141-b-g03-E09","location":{"location_id":"src-b91cee592e-p10-c1r1__v141-a-M01-settlement","page":10,"printed_page":null,"section":null,"anchor_text":"C. Long et al. where BPi 2G is the energy bill for customer i under P2G energy trading. i positive.F","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-10.png","occurrence_role":"formula"},"source_text":"The cost of energy for individual customers with P2P energy sharing is calculated by BP_{2P}^i = \\int_{t=1}^{T} [(NP_t^i - P_{aggBC,t}^i + P_{aggBD,t}^i) \\cdot Pr^t] dt \\tag{36}; where BP_{2P}^i is the energy bill for customer i under P2P energy sharing. Pr^t is the P2P trading price, and the value of the Pr^t depends on the role (i.e. consumer or producer) the customer is playing at time t.","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R007","quote":"The cost of energy for individual customers with P2P energy sharing is calculated by BP_{2P}^i = \\int_{t=1}^{T} [(NP_t^i - P_{aggBC,t}^i + P_{aggBD,t}^i) \\cdot Pr^t] dt \\tag{36}; where BP_{2P}^i is the energy bill for customer i under P2P energy sharing. Pr^t is the P2P trading price, and the value of the Pr^t depends on the role (i.e. consumer or producer) the customer is playing at time t."},{"evidence_id":"v141-b-g03-E10","location":{"location_id":"src-b91cee592e-p10-c2r1__v141-a-M01-settlement","page":10,"printed_page":null,"section":null,"anchor_text":"Applied Energy 226 (2018) 261–276 g. ⎧ Prsellt , NPti −PaggBCi , t + PaggBDi , t \u003c 0 e. t ⎪ Pr = 0 ,","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-10.png","occurrence_role":"formula"},"source_text":"Therefore, Pr^t is calculated by Pr^t = \\left\\{ \\begin{array}{ll} Pr_{sell}^t, & NP_t^i - P_{aggBC,t}^i + P_{aggBD,t}^i \u003c 0 \\\\ Pr_{buy}^t, & NP_t^i - P_{aggBC,t}^i + P_{aggBD,t}^i > 0 \\end{array} \\right. \\tag{37}","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R007","quote":"Therefore, Pr^t is calculated by Pr^t = \\left\\{ \\begin{array}{ll} Pr_{sell}^t, & NP_t^i - P_{aggBC,t}^i + P_{aggBD,t}^i \u003c 0 \\\\ Pr_{buy}^t, & NP_t^i - P_{aggBC,t}^i + P_{aggBD,t}^i > 0 \\end{array} \\right. \\tag{37}"},{"evidence_id":"v141-b-g03-E08","location":{"location_id":"src-b91cee592e-p10-c1r1__v141-a-M01-settlement","page":10,"printed_page":null,"section":null,"anchor_text":"C. Long et al. where BPi 2G is the energy bill for customer i under P2G energy trading. i positive.F","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-10.png","occurrence_role":"formula"},"source_text":"For consumers, P_{ex,t}^i is equal to zero, therefore BP_{2G}^i is always positive. For prosumers, BP_{2G}^i can be positive or negative. When BP_{2G}^i is positive, this means this is the amount of electricity bill the customer needs to pay. When BP_{2G}^i is negative, this means this is the amount of income the customer will be repaid.","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R007","quote":"For consumers, P_{ex,t}^i is equal to zero, therefore BP_{2G}^i is always positive. For prosumers, BP_{2G}^i can be positive or negative. When BP_{2G}^i is positive, this means this is the amount of electricity bill the customer needs to pay. When BP_{2G}^i is negative, this means this is the amount of income the customer will be repaid."}],"candidate_only":true,"classification_subtypes":["compensated_sdr_pricing"],"projection_statuses":["clear"],"taxonomy":{"primary_family":"kind-L6-1c485b92bc","secondary_families":[],"stage":"L6","ontological_kind":"compensated_sdr_pricing"},"semantic_definition":{},"source_units":[{"unit_id":"19-two_stage_battery_sharing::v141-a-M01::pricing.local","paper_id":"19-two_stage_battery_sharing","mechanism_id":"v141-a-M01","function":"pricing.local","source_occurrences":[{"id":"19-two_stage_battery_sharing::v141-c-R005::V::pricing.local","rule_id":"v141-c-R005","market_meaning":"The ESC manages and adjusts the compensating price included in the local P2P pricing mechanism. Scope: Community P2P energy sharing under modified SDR pricing; compensation adjustment informed by customer assessment. The P2P buying price should not exceed the grid buying price, and the P2P selling price should not fall below the grid selling price. Scope: Buying and selling prices within the P2P sharing community. P2P pricing is conducted 24 h after actual electricity consumption using recorded import/export energy data from smart meters. Scope: Ex-post pricing within the P2P sharing community. P2P trading prices are calculated using the SDR method, with the dynamic supply and demand ratio obtained from aggregated metered supply and demand. Scope: Community P2P trading prices calculated from the previous 24 h of premises' smart-metering data. The compensating price is bounded between zero and the difference between the grid buying and selling prices. Scope: Compensating component of the community's modified SDR pricing mechanism. Both P2P selling and buying prices equal the price of electricity bought from the main grid. Scope: Community P2P buying and selling prices at time t. Condition: SDR^{t} = 0; there is no selling power in the community. Both P2P selling and buying prices equal the grid selling price plus the compensating price. Scope: Community P2P buying and selling prices at time t. Condition: SDR^{t} = 1; community selling power equals buying power.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"pricing","context_text":"Buying and selling prices within the P2P sharing community. | Community P2P buying and selling prices at time t. | Community P2P energy sharing under modified SDR pricing; compensation adjustment informed by customer assessment. | Community P2P trading prices calculated from the previous 24 h of premises' smart-metering data. | Compensating component of the community's modified SDR pricing mechanism. | Ex-post pricing within the P2P sharing community.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e013","v141-b-g01-e014","v141-b-g02-E10","v141-b-g02-E21","v141-b-g02-E23","v141-b-g04-E12"]},"constraint_refs":["19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C001","19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C002","19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C003","19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C004","19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C005","19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C006","19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C007","19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C008","19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C009"],"decision_anchor":"pricing.local","source_rule_sha256":"96395fa5d5e547fb54dd66802ad10eec3cad2948cbd6c7b49fe199d6b9e43676"},{"id":"19-two_stage_battery_sharing::v141-c-R007::V::pricing.local","rule_id":"v141-c-R007","market_meaning":"The ESC administers settlement by calculating individual customer energy bills and ensuring that prosumers’ income balances consumers’ expenditure. Scope: Individual customer settlement in the ESC-operated P2P sharing community. Local P2P pricing determines the electricity bills that prosumers pay or receive as repayments and that consumers pay. Scope: Electricity-bill payments and repayments of prosumers and consumers contracted with the ESC. The source states that the P2P buying-price ceiling implies lower consumer electricity bills under P2P sharing than under P2G trading. Scope: Consumer electricity bills under P2P sharing compared with P2G trading. Condition: The P2P buying price never exceeds the price of electricity bought from the grid. Under this uncompensated pricing case, the source states that prosumer income is undermined while consumers benefit; prosumers may receive less income than without P2P sharing. Scope: The source’s explanation of prosumer income and consumer benefits under uncompensated SDR pricing. Condition: The compensating price is zero and the supply-to-demand ratio exceeds one, so both P2P prices equal the grid selling price. At every studied penetration level, zero compensation is reported to leave some prosumers paying higher electricity bills or receiving lower incomes when participating in P2P sharing. Scope: The reported sensitivity evaluation across the studied penetration levels of PV battery systems. Condition: The compensating price is zero in the reported evaluation. With an appropriate compensating price, modified local SDR pricing is stated to ensure economic benefits for every individual prosumer and consumer, with economic gains described in terms of bill savings or repayments. Scope: Individual prosumer and consumer financial outcomes under modified SDR pricing compared with conventional P2G trading. Condition: The compensating price is appropriately set. Billing is conducted 24 hours after actual electricity consumption using recorded import/export energy data from smart meters, for example half-hourly records. Scope: Customer billing in the proposed two-stage P2P sharing arrangement. The positive value is the amount of electricity bill the prosumer is required to pay. Scope: Prosumer electricity-bill values in the reported financial assessment. Condition: The reported prosumer bill value is positive. The negative value denotes income received by the prosumer. Scope: Prosumer electricity-bill values in the reported financial assessment. Condition: The reported prosumer bill value is negative.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Consumer electricity bills under P2P sharing compared with P2G trading. | Customer billing in the proposed two-stage P2P sharing arrangement. | Electricity-bill payments and repayments of prosumers and consumers contracted with the ESC. | Individual customer settlement in the ESC-operated P2P sharing community. | Individual prosumer and consumer financial outcomes under modified SDR pricing compared with conventional P2G trading. | Prosumer electricity-bill values in the reported financial assessment. | The reported sensitivity evaluation across the studied penetration levels of PV battery systems. | The source’s explanation of prosumer income and consumer benefits under uncompensated SDR pricing.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e002","v141-b-g01-e004","v141-b-g01-e005","v141-b-g01-e006","v141-b-g01-e013","v141-b-g02-E23","v141-b-g03-E13","v141-b-g04-E10","v141-b-g04-E13","v141-b-g04-E15","v141-b-g04-E17"]},"constraint_refs":["19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C002","19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C003","19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C004","19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C005","19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C006","19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C011","19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C012","19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C013","19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C014"],"decision_anchor":"settlement.payment","source_rule_sha256":"bd880e891130c0f37fb74ec2eeadfc37b72ff840ddc75d6776e532b766029c31"}],"constraints":[{"constraint_id":"v141-c-R005-C001","kind":"procedural","role":"core","statement":"The ESC manages and adjusts the compensating price included in the local P2P pricing mechanism. Scope: Community P2P energy sharing under modified SDR pricing; compensation adjustment informed by customer assessment.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","pricing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e014","v141-b-g02-E10","v141-b-g04-E12"],"ref":"19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C001","source_rule_id":"v141-c-R005","evidence":[{"evidence_id":"v141-b-g01-e014","location":{"location_id":"src-b91cee592e-p03-c2r4__v141-a-M01-participation","page":3,"printed_page":"263","section":"1. Introduction","anchor_text":"m DERs, because the pricing and billing are conducted 24 h after the ng actual electricity consumpti","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"restatement"},"source_text":"An innovative P2P pricing mechanism was developed to ensure all customers in a community gain economic benefits, i.e. being better off compared to the conventional P2G trading. This pricing mechanism is modified from a previous SDR mechanism to include a compensating price. The modified pricing mechanism can be used as a benchmark applicable to any P2P energy sharing model."},{"evidence_id":"v141-b-g02-E10","location":{"location_id":"src-b91cee592e-p06-c1r2__v141-a-M01-coordination","page":6,"printed_page":null,"section":null,"anchor_text":"psumer premises. The purposes of the control is to minimize the amount of electricity fed back to th","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"In the second block, the smart metering data at all the premises in the community are collected to calculate the aggregated supply and demand at different times of the day (for the previous 24 h). The dynamic supply and demand ratio is used to calculate the P2P trading prices using the SDR method. In practice, this is done 24 h after the actual electricity consumption, and therefore there are no iterations between the pricing and control activities. Finally, the assessment of the P2P energy sharing is carried out. In the community level, the self-consumption and self-sufficiency rate of the community, and the energy cost are analyzed. In the individual customer level, the energy cost of each customer is calculated and a participating willingness index is introduced to evaluate the willingness of prosumers participating in P2P energy sharing. This in turn helps the ESC to adjust the compensating price, which is used to ensure all customers in the community gain economic benefit."},{"evidence_id":"v141-b-g04-E12","location":{"location_id":"src-b91cee592e-p14-c1r4__v141-a-M01-participation","page":14,"printed_page":null,"section":null,"anchor_text":"participation willingness, the lowest compensating prices were 4, 3.5, en 6, 8.5 and 7.5 pence, resp","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-14.png","occurrence_role":"condition"},"source_text":"Therefore, the penetration level of the PV battery systems in a community and the compensating prices managed by the ESC are the main factors to impact the participating willingness for P2P energy sharing, and they should be considered by prosumers and energy service companies when they initialize for P2P energy sharing."}]},{"constraint_id":"v141-c-R005-C002","kind":"mathematical","role":"core","statement":"The P2P buying price should not exceed the grid buying price, and the P2P selling price should not fall below the grid selling price. Scope: Buying and selling prices within the P2P sharing community.","expression":"Pr_{buy}^{t} \\le \\lambda_{buy,t}, \\qquad Pr_{sell}^{t} \\ge \\lambda_{sell,t}","formalization_origin":"source","template_id":null,"members":["pricing.local"],"variable_refs":[],"parameter_refs":["v141-c-R005-theta-lambda-buy","v141-c-R005-theta-lambda-sell"],"evidence_ids":["v141-b-g02-E21"],"ref":"19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C002","source_rule_id":"v141-c-R005","evidence":[{"evidence_id":"v141-b-g02-E21","location":{"location_id":"src-b91cee592e-p08-c2r2__v141-a-M01-pricing","page":8,"printed_page":null,"section":null,"anchor_text":"λ ( λ sell t + )·λbuy , , t3) 0 ⩽ SDRt ⩽ 1 ⎧ SDR − t + λ )· sell (λ buy , t − λ , t λ sell , t + λ t","equation_id":"(19)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"The P2P buying price (Pr_{buy}^{t}) should not be higher than the price of electricity bought from the grid (\\lambda_{buy,t}) and the P2P selling price (Pr_{sell}^{t}) should not be lower than the price of electricity sold to the grid (\\lambda_{sell,t}). Therefore, the P2P selling and buying prices are defined as a function of the SDR. They are shown as Pr_{sell}^{t} = f(SDR^{t}) = \\begin{cases} \\frac{(\\lambda_{sell,t} + \\lambda)\\lambda_{buy,t}}{(\\lambda_{buy,t} - \\lambda_{sell,t} - \\lambda)SDR^{t} + \\lambda_{sell,t} + \\lambda}, & 0 \\le SDR^{t} \\le 1 \\\\ \\lambda_{sell,t} + \\frac{\\lambda}{SDR^{t}}, & SDR^{t} > 1 \\end{cases} \\quad (19)"}]},{"constraint_id":"v141-c-R005-C003","kind":"procedural","role":"core","statement":"P2P pricing is conducted 24 h after actual electricity consumption using recorded import/export energy data from smart meters. Scope: Ex-post pricing within the P2P sharing community.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e013"],"ref":"19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C003","source_rule_id":"v141-c-R005","evidence":[{"evidence_id":"v141-b-g01-e013","location":{"location_id":"src-b91cee592e-p03-c2r3__v141-a-M01-coordination","page":3,"printed_page":"263","section":"1. Introduction","anchor_text":"in munity point of view, e.g. [19]. A thorough assessment method is ﬀ required to analyze the beneﬁt","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"restatement"},"source_text":"A novel two-stage aggregated control framework was proposed to realize P2P energy sharing in low voltage distribution networks. Comparing to the previous works of P2P energy sharing with a third party entity, this control framework requires for very limited measurements and a one-way communication, providing a feasible and practical solution to P2P energy sharing. Compared to the P2P energy sharing without an intermedia, there is no need of fast communication between the market operator and the individual DERs, because the pricing and billing are conducted 24 h after the actual electricity consumption, using the recorded import/export energy (e.g. half-hourly) data from smart meters. Also, there are no divergence issues."}]},{"constraint_id":"v141-c-R005-C004","kind":"mathematical","role":"core","statement":"P2P trading prices are calculated using the SDR method, with the dynamic supply and demand ratio obtained from aggregated metered supply and demand. Scope: Community P2P trading prices calculated from the previous 24 h of premises' smart-metering data.","expression":"\\mathrm{SDR}^{t} = \\frac{\\sum_{i=1}^{N_B} \\left( P_{PV,t}^{i} - P_{aggBC,t}^{i} + P_{aggBD,t}^{i} \\right)}{\\sum_{i=1}^{N} P_{L,t}^{i}}","formalization_origin":"source","template_id":null,"members":["pricing.local"],"variable_refs":[],"parameter_refs":["v141-c-R005-theta-SDR","v141-c-R005-theta-P-PV","v141-c-R005-theta-P-aggBC","v141-c-R005-theta-P-aggBD","v141-c-R005-theta-P-L"],"evidence_ids":["v141-b-g02-E10","v141-b-g02-E21","v141-b-g02-E19"],"ref":"19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C004","source_rule_id":"v141-c-R005","evidence":[{"evidence_id":"v141-b-g02-E10","location":{"location_id":"src-b91cee592e-p06-c1r2__v141-a-M01-coordination","page":6,"printed_page":null,"section":null,"anchor_text":"psumer premises. The purposes of the control is to minimize the amount of electricity fed back to th","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"In the second block, the smart metering data at all the premises in the community are collected to calculate the aggregated supply and demand at different times of the day (for the previous 24 h). The dynamic supply and demand ratio is used to calculate the P2P trading prices using the SDR method. In practice, this is done 24 h after the actual electricity consumption, and therefore there are no iterations between the pricing and control activities. Finally, the assessment of the P2P energy sharing is carried out. In the community level, the self-consumption and self-sufficiency rate of the community, and the energy cost are analyzed. In the individual customer level, the energy cost of each customer is calculated and a participating willingness index is introduced to evaluate the willingness of prosumers participating in P2P energy sharing. This in turn helps the ESC to adjust the compensating price, which is used to ensure all customers in the community gain economic benefit."},{"evidence_id":"v141-b-g02-E21","location":{"location_id":"src-b91cee592e-p08-c2r2__v141-a-M01-pricing","page":8,"printed_page":null,"section":null,"anchor_text":"λ ( λ sell t + )·λbuy , , t3) 0 ⩽ SDRt ⩽ 1 ⎧ SDR − t + λ )· sell (λ buy , t − λ , t λ sell , t + λ t","equation_id":"(19)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"The P2P buying price (Pr_{buy}^{t}) should not be higher than the price of electricity bought from the grid (\\lambda_{buy,t}) and the P2P selling price (Pr_{sell}^{t}) should not be lower than the price of electricity sold to the grid (\\lambda_{sell,t}). Therefore, the P2P selling and buying prices are defined as a function of the SDR. They are shown as Pr_{sell}^{t} = f(SDR^{t}) = \\begin{cases} \\frac{(\\lambda_{sell,t} + \\lambda)\\lambda_{buy,t}}{(\\lambda_{buy,t} - \\lambda_{sell,t} - \\lambda)SDR^{t} + \\lambda_{sell,t} + \\lambda}, & 0 \\le SDR^{t} \\le 1 \\\\ \\lambda_{sell,t} + \\frac{\\lambda}{SDR^{t}}, & SDR^{t} > 1 \\end{cases} \\quad (19)"},{"evidence_id":"v141-b-g02-E19","location":{"location_id":"src-b91cee592e-p08-c1r4__v141-a-M01-pricing","page":8,"printed_page":null,"section":null,"anchor_text":"3.3. P2P trading mechanism Given the fact that in economics the relation between price and SDR is in","equation_id":"(17)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"Given the fact that in economics the relation between price and SDR is inverse-proportional, reference [13] formulated a P2P pricing model based on the supply and demand ratio. Here, the SDR method is also used. The total selling power is from the PV battery systems, which is equal to the remaining PV power after carrying out the charging or discharging activities, and the total buying power is the customer demand. Thus, the SDR at a community Microgrid at time t is defined as, SDR^{t} = \\frac{\\sum_{i=1}^{NB} (P_{PV,t}^{i} - P_{aggBC,t}^{i} + P_{aggBD,t}^{i})}{\\sum_{i=1}^{N} P_{L,t}^{i}} \\quad (17)"}]},{"constraint_id":"v141-c-R005-C005","kind":"mathematical","role":"core","statement":"The compensating price is bounded between zero and the difference between the grid buying and selling prices. Scope: Compensating component of the community's modified SDR pricing mechanism.","expression":"0 \\le \\lambda \\le \\lambda_{buy,t} - \\lambda_{sell,t}","formalization_origin":"source","template_id":null,"members":["pricing.local"],"variable_refs":[],"parameter_refs":["v141-c-R005-theta-lambda","v141-c-R005-theta-lambda-buy","v141-c-R005-theta-lambda-sell"],"evidence_ids":["v141-b-g02-E23"],"ref":"19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C005","source_rule_id":"v141-c-R005","evidence":[{"evidence_id":"v141-b-g02-E23","location":{"location_id":"src-b91cee592e-p08-c2r3__v141-a-M01-pricing","page":8,"printed_page":null,"section":null,"anchor_text":"prices would dynamically change according to Eqs. (19) and (20). The relation of the P2P buying/sell","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"condition"},"source_text":"When SDR^{t} = 0, there is no selling power in the community, and all the required energy is bought from the main grid. The P2P selling and buying prices are both equal to the price of electricity bought from the grid (i.e. Pr_{sell}^{t} = Pr_{buy}^{t} = \\lambda_{buy,t}). When SDR^{t} = 1, the selling power is equal to the buying power in the community, and no power is required to import from (or export to) the main grid. The P2P selling and buying prices are both equal to the price of electricity sold to the grid with a compensation (i.e. Pr_{sell}^{t} = Pr_{buy}^{t} = \\lambda_{sell,t} + \\lambda). Here, \\lambda is a compensating price (0 \\le \\lambda \\le \\lambda_{buy,t} - \\lambda_{sell,t}), and it is used to compensate the prosumers to ensure the prosumers be better off when they participate in P2P energy sharing. When 0 \u003c SDR^{t} \u003c 1, or SDR^{t} > 1, the P2P selling and buying prices would dynamically change according to Eqs. (19) and (20). The reason for introducing the compensating price is that, when there is no compensating price (i.e. \\lambda = 0), both P2P selling and buying prices are equal to the price of electricity sold to grid when the SDR is more than 1. This will undermine the prosumers' income, but provide economic benefits to the consumers (i.e. these who do not have PV battery systems). It might happen that the prosumers receive lower incomes than the case of not participating in P2P energy sharing."}]},{"constraint_id":"v141-c-R005-C006","kind":"mathematical","role":"core","statement":"Both P2P selling and buying prices equal the price of electricity bought from the main grid. Scope: Community P2P buying and selling prices at time t. Condition: SDR^{t} = 0; there is no selling power in the community.","expression":"\\mathrm{SDR}^{t}=0 \\;\\Rightarrow\\; Pr_{sell}^{t}=Pr_{buy}^{t}=\\lambda_{buy,t}","formalization_origin":"source","template_id":null,"members":["pricing.local"],"variable_refs":[],"parameter_refs":["v141-c-R005-theta-SDR","v141-c-R005-theta-lambda-buy"],"evidence_ids":["v141-b-g02-E23"],"ref":"19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C006","source_rule_id":"v141-c-R005","evidence":[{"evidence_id":"v141-b-g02-E23","location":{"location_id":"src-b91cee592e-p08-c2r3__v141-a-M01-pricing","page":8,"printed_page":null,"section":null,"anchor_text":"prices would dynamically change according to Eqs. (19) and (20). The relation of the P2P buying/sell","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"condition"},"source_text":"When SDR^{t} = 0, there is no selling power in the community, and all the required energy is bought from the main grid. The P2P selling and buying prices are both equal to the price of electricity bought from the grid (i.e. Pr_{sell}^{t} = Pr_{buy}^{t} = \\lambda_{buy,t}). When SDR^{t} = 1, the selling power is equal to the buying power in the community, and no power is required to import from (or export to) the main grid. The P2P selling and buying prices are both equal to the price of electricity sold to the grid with a compensation (i.e. Pr_{sell}^{t} = Pr_{buy}^{t} = \\lambda_{sell,t} + \\lambda). Here, \\lambda is a compensating price (0 \\le \\lambda \\le \\lambda_{buy,t} - \\lambda_{sell,t}), and it is used to compensate the prosumers to ensure the prosumers be better off when they participate in P2P energy sharing. When 0 \u003c SDR^{t} \u003c 1, or SDR^{t} > 1, the P2P selling and buying prices would dynamically change according to Eqs. (19) and (20). The reason for introducing the compensating price is that, when there is no compensating price (i.e. \\lambda = 0), both P2P selling and buying prices are equal to the price of electricity sold to grid when the SDR is more than 1. This will undermine the prosumers' income, but provide economic benefits to the consumers (i.e. these who do not have PV battery systems). It might happen that the prosumers receive lower incomes than the case of not participating in P2P energy sharing."}]},{"constraint_id":"v141-c-R005-C007","kind":"mathematical","role":"core","statement":"Both P2P selling and buying prices equal the grid selling price plus the compensating price. Scope: Community P2P buying and selling prices at time t. Condition: SDR^{t} = 1; community selling power equals buying power.","expression":"\\mathrm{SDR}^{t}=1 \\;\\Rightarrow\\; Pr_{sell}^{t}=Pr_{buy}^{t}=\\lambda_{sell,t}+\\lambda","formalization_origin":"source","template_id":null,"members":["pricing.local"],"variable_refs":[],"parameter_refs":["v141-c-R005-theta-SDR","v141-c-R005-theta-lambda-sell","v141-c-R005-theta-lambda"],"evidence_ids":["v141-b-g02-E23"],"ref":"19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C007","source_rule_id":"v141-c-R005","evidence":[{"evidence_id":"v141-b-g02-E23","location":{"location_id":"src-b91cee592e-p08-c2r3__v141-a-M01-pricing","page":8,"printed_page":null,"section":null,"anchor_text":"prices would dynamically change according to Eqs. (19) and (20). The relation of the P2P buying/sell","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"condition"},"source_text":"When SDR^{t} = 0, there is no selling power in the community, and all the required energy is bought from the main grid. The P2P selling and buying prices are both equal to the price of electricity bought from the grid (i.e. Pr_{sell}^{t} = Pr_{buy}^{t} = \\lambda_{buy,t}). When SDR^{t} = 1, the selling power is equal to the buying power in the community, and no power is required to import from (or export to) the main grid. The P2P selling and buying prices are both equal to the price of electricity sold to the grid with a compensation (i.e. Pr_{sell}^{t} = Pr_{buy}^{t} = \\lambda_{sell,t} + \\lambda). Here, \\lambda is a compensating price (0 \\le \\lambda \\le \\lambda_{buy,t} - \\lambda_{sell,t}), and it is used to compensate the prosumers to ensure the prosumers be better off when they participate in P2P energy sharing. When 0 \u003c SDR^{t} \u003c 1, or SDR^{t} > 1, the P2P selling and buying prices would dynamically change according to Eqs. (19) and (20). The reason for introducing the compensating price is that, when there is no compensating price (i.e. \\lambda = 0), both P2P selling and buying prices are equal to the price of electricity sold to grid when the SDR is more than 1. This will undermine the prosumers' income, but provide economic benefits to the consumers (i.e. these who do not have PV battery systems). It might happen that the prosumers receive lower incomes than the case of not participating in P2P energy sharing."}]},{"constraint_id":"v141-c-R005-C008","kind":"mathematical","role":"core","statement":"The P2P selling price is defined by the source as a piecewise function of the SDR, the grid buying and selling prices, and the compensating price. Scope: Community P2P selling price at time t.","expression":"Pr_{sell}^{t} = \\begin{cases} \\frac{(\\lambda_{sell,t}+\\lambda)\\lambda_{buy,t}}{(\\lambda_{buy,t}-\\lambda_{sell,t}-\\lambda)\\mathrm{SDR}^{t}+\\lambda_{sell,t}+\\lambda}, & 0 \\le \\mathrm{SDR}^{t} \\le 1 \\\\ \\lambda_{sell,t}+\\frac{\\lambda}{\\mathrm{SDR}^{t}}, & \\mathrm{SDR}^{t}>1 \\end{cases}","formalization_origin":"source","template_id":null,"members":["pricing.local"],"variable_refs":[],"parameter_refs":["v141-c-R005-theta-SDR","v141-c-R005-theta-lambda","v141-c-R005-theta-lambda-buy","v141-c-R005-theta-lambda-sell"],"evidence_ids":["v141-b-g02-E21"],"ref":"19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C008","source_rule_id":"v141-c-R005","evidence":[{"evidence_id":"v141-b-g02-E21","location":{"location_id":"src-b91cee592e-p08-c2r2__v141-a-M01-pricing","page":8,"printed_page":null,"section":null,"anchor_text":"λ ( λ sell t + )·λbuy , , t3) 0 ⩽ SDRt ⩽ 1 ⎧ SDR − t + λ )· sell (λ buy , t − λ , t λ sell , t + λ t","equation_id":"(19)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"The P2P buying price (Pr_{buy}^{t}) should not be higher than the price of electricity bought from the grid (\\lambda_{buy,t}) and the P2P selling price (Pr_{sell}^{t}) should not be lower than the price of electricity sold to the grid (\\lambda_{sell,t}). Therefore, the P2P selling and buying prices are defined as a function of the SDR. They are shown as Pr_{sell}^{t} = f(SDR^{t}) = \\begin{cases} \\frac{(\\lambda_{sell,t} + \\lambda)\\lambda_{buy,t}}{(\\lambda_{buy,t} - \\lambda_{sell,t} - \\lambda)SDR^{t} + \\lambda_{sell,t} + \\lambda}, & 0 \\le SDR^{t} \\le 1 \\\\ \\lambda_{sell,t} + \\frac{\\lambda}{SDR^{t}}, & SDR^{t} > 1 \\end{cases} \\quad (19)"}]},{"constraint_id":"v141-c-R005-C009","kind":"mathematical","role":"core","statement":"The P2P buying price is defined by the source as a piecewise function of the P2P selling price, the SDR, the grid buying and selling prices, and the compensating price. Scope: Community P2P buying price at time t.","expression":"Pr_{buy}^{t} = \\begin{cases} Pr_{sell}^{t}\\,\\mathrm{SDR}^{t}+\\lambda_{buy,t}(1-\\mathrm{SDR}^{t}), & 0 \\le \\mathrm{SDR}^{t} \\le 1 \\\\ \\lambda_{sell,t}+\\lambda, & \\mathrm{SDR}^{t}>1 \\end{cases}","formalization_origin":"source","template_id":null,"members":["pricing.local"],"variable_refs":[],"parameter_refs":["v141-c-R005-theta-SDR","v141-c-R005-theta-lambda","v141-c-R005-theta-lambda-buy","v141-c-R005-theta-lambda-sell"],"evidence_ids":["v141-b-g02-E22"],"ref":"19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C009","source_rule_id":"v141-c-R005","evidence":[{"evidence_id":"v141-b-g02-E22","location":{"location_id":"src-b91cee592e-p08-c2r2__v141-a-M01-pricing","page":8,"printed_page":null,"section":null,"anchor_text":"λ ( λ sell t + )·λbuy , , t3) 0 ⩽ SDRt ⩽ 1 ⎧ SDR − t + λ )· sell (λ buy , t − λ , t λ sell , t + λ t","equation_id":"(20)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"Pr_{buy}^{t} = f'(SDR^{t}) = \\begin{cases} Pr_{sell}^{t} \\cdot SDR^{t} + \\lambda_{buy,t} \\cdot (1 - SDR^{t}), & 0 \\le SDR^{t} \\le 1 \\\\ \\lambda_{sell,t} + \\lambda, & SDR^{t} > 1 \\end{cases} \\quad (20)"}]},{"constraint_id":"v141-c-R007-C002","kind":"procedural","role":"core","statement":"Local P2P pricing determines the electricity bills that prosumers pay or receive as repayments and that consumers pay. Scope: Electricity-bill payments and repayments of prosumers and consumers contracted with the ESC.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local","settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e005","v141-b-g01-e006"],"ref":"19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C002","source_rule_id":"v141-c-R007","evidence":[{"evidence_id":"v141-b-g01-e005","location":{"location_id":"src-b91cee592e-p04-c2r1__v141-a-M01-participation","page":4,"printed_page":"264","section":"2.1. P2P energy sharing structure","anchor_text":"Applied Energy 226 (2018) 261–276 the power balance of the community; Contract with a supplier for t","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"(2) Prosumers\n• Hand over the control of their batteries to the ESC;\n• Contract with the ESC, pay/repay their electricity bills according to the P2P pricing mechanism (The prices are calculated 24 h after the actual consumption according to the predefined pricing mechanism)."},{"evidence_id":"v141-b-g01-e006","location":{"location_id":"src-b91cee592e-p04-c2r2__v141-a-M01-participation","page":4,"printed_page":"264","section":"2.1. P2P energy sharing structure","anchor_text":"p g ( p he after the actual consumption according to the predeﬁned pricing is mechanism). (3) Consum","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"(3) Consumers\n• Contract with the ESC, pay their electricity bill according to the P2P pricing mechanism (The prices are calculated 24 h after the actual consumption according to the predefined pricing mechanism)."}]},{"constraint_id":"v141-c-R007-C003","kind":"logical","role":"core","statement":"The source states that the P2P buying-price ceiling implies lower consumer electricity bills under P2P sharing than under P2G trading. Scope: Consumer electricity bills under P2P sharing compared with P2G trading. Condition: The P2P buying price never exceeds the price of electricity bought from the grid.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local","settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g03-E13"],"ref":"19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C003","source_rule_id":"v141-c-R007","evidence":[{"evidence_id":"v141-b-g03-E13","location":{"location_id":"src-b91cee592e-p11-c1r2__v141-a-M01-participation","page":11,"printed_page":null,"section":null,"anchor_text":"sharing than under the P2G energy trading. Hence, there is no need to ti evaluate the participation ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-11.png","occurrence_role":"condition"},"source_text":"For the consumers, as the P2P buying price (Pr_{buy}^t) is never higher than the price of electricity bought from the grid (\\lambda_{buy,t}), the energy bill of consumers will be always lower when participating in P2P energy sharing than under the P2G energy trading. Hence, there is no need to evaluate the participation willingness of consumers."}]},{"constraint_id":"v141-c-R007-C004","kind":"logical","role":"core","statement":"Under this uncompensated pricing case, the source states that prosumer income is undermined while consumers benefit; prosumers may receive less income than without P2P sharing. Scope: The source’s explanation of prosumer income and consumer benefits under uncompensated SDR pricing. Condition: The compensating price is zero and the supply-to-demand ratio exceeds one, so both P2P prices equal the grid selling price.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local","settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-E23"],"ref":"19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C004","source_rule_id":"v141-c-R007","evidence":[{"evidence_id":"v141-b-g02-E23","location":{"location_id":"src-b91cee592e-p08-c2r3__v141-a-M01-pricing","page":8,"printed_page":null,"section":null,"anchor_text":"prices would dynamically change according to Eqs. (19) and (20). The relation of the P2P buying/sell","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"condition"},"source_text":"When SDR^{t} = 0, there is no selling power in the community, and all the required energy is bought from the main grid. The P2P selling and buying prices are both equal to the price of electricity bought from the grid (i.e. Pr_{sell}^{t} = Pr_{buy}^{t} = \\lambda_{buy,t}). When SDR^{t} = 1, the selling power is equal to the buying power in the community, and no power is required to import from (or export to) the main grid. The P2P selling and buying prices are both equal to the price of electricity sold to the grid with a compensation (i.e. Pr_{sell}^{t} = Pr_{buy}^{t} = \\lambda_{sell,t} + \\lambda). Here, \\lambda is a compensating price (0 \\le \\lambda \\le \\lambda_{buy,t} - \\lambda_{sell,t}), and it is used to compensate the prosumers to ensure the prosumers be better off when they participate in P2P energy sharing. When 0 \u003c SDR^{t} \u003c 1, or SDR^{t} > 1, the P2P selling and buying prices would dynamically change according to Eqs. (19) and (20). The reason for introducing the compensating price is that, when there is no compensating price (i.e. \\lambda = 0), both P2P selling and buying prices are equal to the price of electricity sold to grid when the SDR is more than 1. This will undermine the prosumers' income, but provide economic benefits to the consumers (i.e. these who do not have PV battery systems). It might happen that the prosumers receive lower incomes than the case of not participating in P2P energy sharing."}]},{"constraint_id":"v141-c-R007-C005","kind":"logical","role":"core","statement":"At every studied penetration level, zero compensation is reported to leave some prosumers paying higher electricity bills or receiving lower incomes when participating in P2P sharing. Scope: The reported sensitivity evaluation across the studied penetration levels of PV battery systems. Condition: The compensating price is zero in the reported evaluation.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local","settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g04-E10"],"ref":"19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C005","source_rule_id":"v141-c-R007","evidence":[{"evidence_id":"v141-b-g04-E10","location":{"location_id":"src-b91cee592e-p14-c1r3__v141-a-M01-participation","page":14,"printed_page":null,"section":null,"anchor_text":"battery, but it only requires to reduce the price of the battery system to ev £430/kWh (only 14% low","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-14.png","occurrence_role":"unknown"},"source_text":"When the compensating price is zero, at all the penetration levels of PV battery systems, some prosumers are paying more electricity bills or gaining lower incomes when participating in P2P energy sharing. This is because the economic beneﬁts were obtained by the consumers, whilst for some of the prosumers, it may not be worth participating in P2P energy sharing."}]},{"constraint_id":"v141-c-R007-C006","kind":"logical","role":"core","statement":"With an appropriate compensating price, modified local SDR pricing is stated to ensure economic benefits for every individual prosumer and consumer, with economic gains described in terms of bill savings or repayments. Scope: Individual prosumer and consumer financial outcomes under modified SDR pricing compared with conventional P2G trading. Condition: The compensating price is appropriately set.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local","settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g04-E15","v141-b-g04-E17"],"ref":"19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C006","source_rule_id":"v141-c-R007","evidence":[{"evidence_id":"v141-b-g04-E15","location":{"location_id":"src-b91cee592e-p15-c1r3__v141-a-M01-participation","page":15,"printed_page":null,"section":null,"anchor_text":"pr This paper proposed a two-stage control method to realize P2P energy sharing in community Microgr","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-15.png","occurrence_role":"restatement"},"source_text":"With an appropriate setting of the compensating price, the modiﬁed supply demand ratio based mechanism ensures every individual customer in the community be better oﬀcompared to the conventional P2G energy trading, i.e. every individual prosumer and consumer gain economic beneﬁts. This pricing mechanism can be used as a benchmark applicable to any P2P energy sharing model."},{"evidence_id":"v141-b-g04-E17","location":{"location_id":"src-b91cee592e-p14-c2r3__v141-a-M01-coordination","page":14,"printed_page":null,"section":null,"anchor_text":"to evolutionary algorithms to achieve the global optimum for P2P energy sharing is considered as one","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-14.png","occurrence_role":"exception"},"source_text":"The unfairness of economic gains may exist, i.e. there are diﬀerences in bill savings (or repayments) among consumers (or prosumers)."}]},{"constraint_id":"v141-c-R007-C011","kind":"mathematical","role":"core","statement":"The individual P2P energy bill for customer i is the time integral over T of the customer’s net position after aggregate battery charging/discharging multiplied by the role-dependent P2P trading price. Scope: Individual customer settlement under P2P sharing.","expression":"BP_{2P}^{i} = \\int_{t=1}^{T} \\left( NP_{t}^{i} - P_{aggBC,t}^{i} + P_{aggBD,t}^{i} \\right) Pr^{t} \\, dt","formalization_origin":"source","template_id":null,"members":["pricing.local","settlement.payment"],"variable_refs":[],"parameter_refs":["theta_NP","theta_P_aggBC","theta_P_aggBD","theta_Pr","theta_T"],"evidence_ids":["v141-b-g03-E09"],"ref":"19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C011","source_rule_id":"v141-c-R007","evidence":[{"evidence_id":"v141-b-g03-E09","location":{"location_id":"src-b91cee592e-p10-c1r1__v141-a-M01-settlement","page":10,"printed_page":null,"section":null,"anchor_text":"C. Long et al. where BPi 2G is the energy bill for customer i under P2G energy trading. i positive.F","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-10.png","occurrence_role":"formula"},"source_text":"The cost of energy for individual customers with P2P energy sharing is calculated by BP_{2P}^i = \\int_{t=1}^{T} [(NP_t^i - P_{aggBC,t}^i + P_{aggBD,t}^i) \\cdot Pr^t] dt \\tag{36}; where BP_{2P}^i is the energy bill for customer i under P2P energy sharing. Pr^t is the P2P trading price, and the value of the Pr^t depends on the role (i.e. consumer or producer) the customer is playing at time t."}]},{"constraint_id":"v141-c-R007-C012","kind":"mathematical","role":"core","statement":"The P2P trading price used in the individual bill is the P2P selling price when the customer’s net position after aggregate battery charging/discharging is negative and the P2P buying price when that net position is positive. Scope: Role-dependent P2P price selection in individual settlement. The source does not print a case for a zero net position.","expression":"Pr^{t} = \\begin{cases} Pr_{sell}^{t}, & NP_{t}^{i} - P_{aggBC,t}^{i} + P_{aggBD,t}^{i} \u003c 0 \\\\ Pr_{buy}^{t}, & NP_{t}^{i} - P_{aggBC,t}^{i} + P_{aggBD,t}^{i} > 0 \\end{cases}","formalization_origin":"source","template_id":null,"members":["pricing.local","settlement.payment"],"variable_refs":[],"parameter_refs":["theta_Pr","theta_Pr_sell","theta_Pr_buy","theta_NP","theta_P_aggBC","theta_P_aggBD"],"evidence_ids":["v141-b-g03-E09","v141-b-g03-E10"],"ref":"19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C012","source_rule_id":"v141-c-R007","evidence":[{"evidence_id":"v141-b-g03-E09","location":{"location_id":"src-b91cee592e-p10-c1r1__v141-a-M01-settlement","page":10,"printed_page":null,"section":null,"anchor_text":"C. Long et al. where BPi 2G is the energy bill for customer i under P2G energy trading. i positive.F","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-10.png","occurrence_role":"formula"},"source_text":"The cost of energy for individual customers with P2P energy sharing is calculated by BP_{2P}^i = \\int_{t=1}^{T} [(NP_t^i - P_{aggBC,t}^i + P_{aggBD,t}^i) \\cdot Pr^t] dt \\tag{36}; where BP_{2P}^i is the energy bill for customer i under P2P energy sharing. Pr^t is the P2P trading price, and the value of the Pr^t depends on the role (i.e. consumer or producer) the customer is playing at time t."},{"evidence_id":"v141-b-g03-E10","location":{"location_id":"src-b91cee592e-p10-c2r1__v141-a-M01-settlement","page":10,"printed_page":null,"section":null,"anchor_text":"Applied Energy 226 (2018) 261–276 g. ⎧ Prsellt , NPti −PaggBCi , t + PaggBDi , t \u003c 0 e. t ⎪ Pr = 0 ,","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-10.png","occurrence_role":"formula"},"source_text":"Therefore, Pr^t is calculated by Pr^t = \\left\\{ \\begin{array}{ll} Pr_{sell}^t, & NP_t^i - P_{aggBC,t}^i + P_{aggBD,t}^i \u003c 0 \\\\ Pr_{buy}^t, & NP_t^i - P_{aggBC,t}^i + P_{aggBD,t}^i > 0 \\end{array} \\right. \\tag{37}"}]},{"constraint_id":"v141-c-R007-C013","kind":"mathematical","role":"supporting","statement":"When the compensating price is zero and the supply-to-demand ratio exceeds one, both P2P selling and buying prices equal the grid selling price. Scope: Price consequence under uncompensated SDR pricing. This formalizes the price-equality part of the source’s uncompensated-pricing statement; the associated income and consumer-benefit conclusions remain qualitative.","expression":"(\\lambda = 0 \\land SDR^{t} > 1) \\Rightarrow \\left( Pr_{sell}^{t} = Pr_{buy}^{t} = \\lambda_{sell,t} \\right)","formalization_origin":"source","template_id":null,"members":["pricing.local","settlement.payment"],"variable_refs":[],"parameter_refs":["theta_lambda_comp","theta_SDR","theta_Pr_sell","theta_Pr_buy","theta_lambda_sell"],"evidence_ids":["v141-b-g02-E23"],"ref":"19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C013","source_rule_id":"v141-c-R007","evidence":[{"evidence_id":"v141-b-g02-E23","location":{"location_id":"src-b91cee592e-p08-c2r3__v141-a-M01-pricing","page":8,"printed_page":null,"section":null,"anchor_text":"prices would dynamically change according to Eqs. (19) and (20). The relation of the P2P buying/sell","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"condition"},"source_text":"When SDR^{t} = 0, there is no selling power in the community, and all the required energy is bought from the main grid. The P2P selling and buying prices are both equal to the price of electricity bought from the grid (i.e. Pr_{sell}^{t} = Pr_{buy}^{t} = \\lambda_{buy,t}). When SDR^{t} = 1, the selling power is equal to the buying power in the community, and no power is required to import from (or export to) the main grid. The P2P selling and buying prices are both equal to the price of electricity sold to the grid with a compensation (i.e. Pr_{sell}^{t} = Pr_{buy}^{t} = \\lambda_{sell,t} + \\lambda). Here, \\lambda is a compensating price (0 \\le \\lambda \\le \\lambda_{buy,t} - \\lambda_{sell,t}), and it is used to compensate the prosumers to ensure the prosumers be better off when they participate in P2P energy sharing. When 0 \u003c SDR^{t} \u003c 1, or SDR^{t} > 1, the P2P selling and buying prices would dynamically change according to Eqs. (19) and (20). The reason for introducing the compensating price is that, when there is no compensating price (i.e. \\lambda = 0), both P2P selling and buying prices are equal to the price of electricity sold to grid when the SDR is more than 1. This will undermine the prosumers' income, but provide economic benefits to the consumers (i.e. these who do not have PV battery systems). It might happen that the prosumers receive lower incomes than the case of not participating in P2P energy sharing."}]},{"constraint_id":"v141-c-R007-C014","kind":"mathematical","role":"supporting","statement":"For a consumer with no export, if the P2P buying price never exceeds the grid buying price at each time, the consumer’s P2P energy bill is lower than the P2G bill. Scope: Consumer bill comparison under the P2P buying-price ceiling.","expression":"\\left( \\forall t,\\; Pr_{buy}^{t} \\le \\lambda_{buy,t} \\right) \\land \\left( \\forall t,\\; P_{ex,t}^{i} = 0 \\right) \\Rightarrow BP_{2P}^{i} \u003c BP_{2G}^{i}","formalization_origin":"source","template_id":null,"members":["pricing.local","settlement.payment"],"variable_refs":[],"parameter_refs":["theta_Pr_buy","theta_lambda_buy","theta_P_ex"],"evidence_ids":["v141-b-g03-E13","v141-b-g03-E08"],"ref":"19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C014","source_rule_id":"v141-c-R007","evidence":[{"evidence_id":"v141-b-g03-E13","location":{"location_id":"src-b91cee592e-p11-c1r2__v141-a-M01-participation","page":11,"printed_page":null,"section":null,"anchor_text":"sharing than under the P2G energy trading. Hence, there is no need to ti evaluate the participation ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-11.png","occurrence_role":"condition"},"source_text":"For the consumers, as the P2P buying price (Pr_{buy}^t) is never higher than the price of electricity bought from the grid (\\lambda_{buy,t}), the energy bill of consumers will be always lower when participating in P2P energy sharing than under the P2G energy trading. Hence, there is no need to evaluate the participation willingness of consumers."},{"evidence_id":"v141-b-g03-E08","location":{"location_id":"src-b91cee592e-p10-c1r1__v141-a-M01-settlement","page":10,"printed_page":null,"section":null,"anchor_text":"C. Long et al. where BPi 2G is the energy bill for customer i under P2G energy trading. i positive.F","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-10.png","occurrence_role":"formula"},"source_text":"For consumers, P_{ex,t}^i is equal to zero, therefore BP_{2G}^i is always positive. For prosumers, BP_{2G}^i can be positive or negative. When BP_{2G}^i is positive, this means this is the amount of electricity bill the customer needs to pay. When BP_{2G}^i is negative, this means this is the amount of income the customer will be repaid."}]}],"variables":[],"parameters":[{"parameter_id":"v141-c-R005-theta-SDR","symbol":"SDR^{t}","meaning":"Supply and demand ratio at the community Microgrid at time t, computed from aggregated metered supply and demand for the previous 24 h and used as an input to the local P2P price formulas.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"dimensionless","indices":["t"],"evidence_ids":["v141-b-g02-E10","v141-b-g02-E19","v141-b-g02-E21"],"source_rule_id":"v141-c-R005","declaration_ref":"19-two_stage_battery_sharing::v141-c-R005::theta::v141-c-R005-theta-SDR"},{"parameter_id":"v141-c-R005-theta-lambda","symbol":"\\lambda","meaning":"Compensating price used to ensure prosumers are better off when participating in P2P energy sharing; bounded between zero and the difference between the grid buying and selling prices. It has the same price dimension as the grid buying and selling prices.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-E10","v141-b-g02-E21","v141-b-g02-E23","v141-b-g04-E12"],"source_rule_id":"v141-c-R005","declaration_ref":"19-two_stage_battery_sharing::v141-c-R005::theta::v141-c-R005-theta-lambda"},{"parameter_id":"v141-c-R005-theta-lambda-buy","symbol":"\\lambda_{buy,t}","meaning":"Price of electricity bought from the grid at time t, used in the local P2P pricing formulas and as the upper bound for the P2P buying price.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"pence/kWh (case-study reporting)","indices":["t"],"evidence_ids":["v141-b-g02-E21","v141-b-g02-E23"],"source_rule_id":"v141-c-R005","declaration_ref":"19-two_stage_battery_sharing::v141-c-R005::theta::v141-c-R005-theta-lambda-buy"},{"parameter_id":"v141-c-R005-theta-lambda-sell","symbol":"\\lambda_{sell,t}","meaning":"Price of electricity sold to the grid at time t, used in the local P2P pricing formulas and as the lower bound for the P2P selling price.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"pence/kWh (case-study reporting)","indices":["t"],"evidence_ids":["v141-b-g02-E21","v141-b-g02-E23"],"source_rule_id":"v141-c-R005","declaration_ref":"19-two_stage_battery_sharing::v141-c-R005::theta::v141-c-R005-theta-lambda-sell"},{"parameter_id":"v141-c-R005-theta-P-PV","symbol":"P_{PV,t}^{i}","meaning":"PV generation power of prosumer i at time t, appearing in the SDR numerator in Eq. (17).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kW","indices":["i","t"],"evidence_ids":["v141-b-g02-E19"],"source_rule_id":"v141-c-R005","declaration_ref":"19-two_stage_battery_sharing::v141-c-R005::theta::v141-c-R005-theta-P-PV"},{"parameter_id":"v141-c-R005-theta-P-aggBC","symbol":"P_{aggBC,t}^{i}","meaning":"Battery charging power allocated to prosumer i at time t, subtracted in the SDR numerator in Eq. (17).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kW","indices":["i","t"],"evidence_ids":["v141-b-g02-E17","v141-b-g02-E19"],"source_rule_id":"v141-c-R005","declaration_ref":"19-two_stage_battery_sharing::v141-c-R005::theta::v141-c-R005-theta-P-aggBC"},{"parameter_id":"v141-c-R005-theta-P-aggBD","symbol":"P_{aggBD,t}^{i}","meaning":"Battery discharging power allocated to prosumer i at time t, added in the SDR numerator in Eq. (17).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kW","indices":["i","t"],"evidence_ids":["v141-b-g02-E18","v141-b-g02-E19"],"source_rule_id":"v141-c-R005","declaration_ref":"19-two_stage_battery_sharing::v141-c-R005::theta::v141-c-R005-theta-P-aggBD"},{"parameter_id":"v141-c-R005-theta-P-L","symbol":"P_{L,t}^{i}","meaning":"Power consumption of customer i at time t, appearing in the SDR denominator in Eq. (17).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kW","indices":["i","t"],"evidence_ids":["v141-b-g02-E19"],"source_rule_id":"v141-c-R005","declaration_ref":"19-two_stage_battery_sharing::v141-c-R005::theta::v141-c-R005-theta-P-L"},{"parameter_id":"theta_lambda_buy","symbol":"\\lambda_{buy,t}","meaning":"Price of electricity bought from the grid at time t; used in the P2G bill and the P2P buying-price ceiling.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"currency/kWh","indices":["t"],"evidence_ids":["v141-b-g03-E07","v141-b-g03-E08","v141-b-g02-E21"],"source_rule_id":"v141-c-R007","declaration_ref":"19-two_stage_battery_sharing::v141-c-R007::theta::theta_lambda_buy"},{"parameter_id":"theta_lambda_sell","symbol":"\\lambda_{sell,t}","meaning":"Price of electricity sold to the grid at time t; used in the P2G bill, the compensating-price bound, and the uncompensated-price equality.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"currency/kWh","indices":["t"],"evidence_ids":["v141-b-g03-E07","v141-b-g03-E08","v141-b-g02-E23"],"source_rule_id":"v141-c-R007","declaration_ref":"19-two_stage_battery_sharing::v141-c-R007::theta::theta_lambda_sell"},{"parameter_id":"theta_lambda_comp","symbol":"\\lambda","meaning":"Compensating price in the modified SDR pricing, bounded in the source by 0 \u003c= lambda \u003c= lambda_buy,t - lambda_sell,t.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"currency/kWh","indices":[],"evidence_ids":["v141-b-g02-E23","v141-b-g04-E09","v141-b-g04-E10"],"source_rule_id":"v141-c-R007","declaration_ref":"19-two_stage_battery_sharing::v141-c-R007::theta::theta_lambda_comp"},{"parameter_id":"theta_P_ex","symbol":"P_{ex,t}^{i}","meaning":"Power exported to the grid by customer i at time t, as recorded by the individual premises smart meter for the P2G bill.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kW","indices":["i","t"],"evidence_ids":["v141-b-g03-E07","v141-b-g03-E08"],"source_rule_id":"v141-c-R007","declaration_ref":"19-two_stage_battery_sharing::v141-c-R007::theta::theta_P_ex"},{"parameter_id":"theta_NP","symbol":"NP_{t}^{i}","meaning":"Net-load term for customer i at time t used in the P2P bill; the source defines NP_t^i for prosumers and Eq. (36) applies the term at individual-customer level.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kW","indices":["i","t"],"evidence_ids":["v141-b-g01-e008","v141-b-g03-E09"],"source_rule_id":"v141-c-R007","declaration_ref":"19-two_stage_battery_sharing::v141-c-R007::theta::theta_NP"},{"parameter_id":"theta_P_aggBC","symbol":"P_{aggBC,t}^{i}","meaning":"Aggregate battery charging power term for customer i at time t entering the P2P individual bill, taken as a prior-stage/recorded settlement input.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kW","indices":["i","t"],"evidence_ids":["v141-b-g03-E09","v141-b-g02-E17"],"source_rule_id":"v141-c-R007","declaration_ref":"19-two_stage_battery_sharing::v141-c-R007::theta::theta_P_aggBC"},{"parameter_id":"theta_P_aggBD","symbol":"P_{aggBD,t}^{i}","meaning":"Aggregate battery discharging power term for customer i at time t entering the P2P individual bill, taken as a prior-stage/recorded settlement input.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kW","indices":["i","t"],"evidence_ids":["v141-b-g03-E09","v141-b-g02-E18"],"source_rule_id":"v141-c-R007","declaration_ref":"19-two_stage_battery_sharing::v141-c-R007::theta::theta_P_aggBD"},{"parameter_id":"theta_Pr_sell","symbol":"Pr_{sell}^{t}","meaning":"P2P selling price at time t from local SDR pricing, selected in the individual bill when the customer has a negative net position.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"currency/kWh","indices":["t"],"evidence_ids":["v141-b-g02-E20","v141-b-g02-E21","v141-b-g03-E10"],"source_rule_id":"v141-c-R007","declaration_ref":"19-two_stage_battery_sharing::v141-c-R007::theta::theta_Pr_sell"},{"parameter_id":"theta_Pr_buy","symbol":"Pr_{buy}^{t}","meaning":"P2P buying price at time t from local SDR pricing, selected in the individual bill when the customer has a positive net position.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"currency/kWh","indices":["t"],"evidence_ids":["v141-b-g02-E20","v141-b-g02-E22","v141-b-g03-E10"],"source_rule_id":"v141-c-R007","declaration_ref":"19-two_stage_battery_sharing::v141-c-R007::theta::theta_Pr_buy"},{"parameter_id":"theta_Pr","symbol":"Pr^{t}","meaning":"Role-dependent P2P trading price at time t used in the individual P2P bill and selected by Eq. (37).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"currency/kWh","indices":["t"],"evidence_ids":["v141-b-g03-E09","v141-b-g03-E10"],"source_rule_id":"v141-c-R007","declaration_ref":"19-two_stage_battery_sharing::v141-c-R007::theta::theta_Pr"},{"parameter_id":"theta_SDR","symbol":"SDR^{t}","meaning":"Supply-to-demand ratio at the community Microgrid at time t, used as the pricing condition for the uncompensated-price case.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"dimensionless","indices":["t"],"evidence_ids":["v141-b-g02-E19","v141-b-g02-E23"],"source_rule_id":"v141-c-R007","declaration_ref":"19-two_stage_battery_sharing::v141-c-R007::theta::theta_SDR"},{"parameter_id":"theta_T","symbol":"T","meaning":"Number of time slots over the operation time period, used as the integral horizon in the individual bill formulas.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"time slots","indices":[],"evidence_ids":["v141-b-g01-e008"],"source_rule_id":"v141-c-R007","declaration_ref":"19-two_stage_battery_sharing::v141-c-R007::theta::theta_T"}]}],"source_definitions":[{"unit_id":"19-two_stage_battery_sharing::v141-a-M01::pricing.local","stage":"L6","subtype":"compensated_sdr_pricing","projection_status":"clear","target_definition":"The P2P buying and selling unit prices are formed according to the aggregate metered supply-demand ratio SDR^t, the grid purchase and sale prices, and the compensation price λ. When 0≤SDR^t≤1, Pr_{sell}^t=((λ_{sell,t}+λ)λ_{buy,t})/((λ_{buy,t}-λ_{sell,t}-λ)SDR^t+λ_{sell,t}+λ), Pr_{buy}^t=Pr_{sell}^t·SDR^t+λ_{buy,t}(1-SDR^t); when SDR^t>1, Pr_{sell}^t=λ_{sell,t}+λ/SDR^t, Pr_{buy}^t=λ_{sell,t}+λ.","form_kind":"mathematical","identity_fields":["Object: community P2P electricity purchase and sale unit prices","Core operation: piecewise pricing based on the aggregate supply-demand ratio, external electricity prices, and the compensation term","Output: Pr_{buy}^t and Pr_{sell}^t"],"variation_fields":["SDR^t=[sum_{i=1}^{N_B}(P_{PV,t}^i-P_{aggBC,t}^i+P_{aggBD,t}^i)]/[sum_{i=1}^{N}P_{L,t}^i]","Pricing is recorded using smart meters after 24 h of consumption; there is no iteration between price and control activities","0≤λ≤λ_{buy,t}-λ_{sell,t}; the ESC adjusts the compensation price based on customer assessment","Price bounds: Pr_{buy}^t≤λ_{buy,t}, Pr_{sell}^t≥λ_{sell,t}","The source specifies the endpoints: when SDR^t=0, both prices are λ_{buy,t}; when SDR^t=1, both prices are λ_{sell,t}+λ","The bill selects the already-formed buying price or selling price according to the customer's net position; the original text does not list the zero net position case"],"constraint_refs":["19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C001","19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C002","19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C003","19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C004","19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C005","19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C006","19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C007","19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C008","19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C009","19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C012"],"paper_id":"19-two_stage_battery_sharing","mechanism_id":"v141-a-M01","function":"pricing.local","template_code":"JOC"}],"source_variants":[],"functional":{"is_child":false,"subdivision_pending":false},"canonical_pointer":"/nodes/229"});
